      "EN: Keep energy as a hedge, not a hero trade; Iran and Strait of Hormuz headlines cooled, but Treasury sanctions kept the tail risk alive. | 中文：把能源当作对冲而不是主线英雄交易；伊朗与霍尔木兹海峡 headlines 虽然降温，但财政部制裁仍让尾部风险存在。",
